CREATE TABLE users(id uuid PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, recovery_hash text, preferences jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id text PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, csrf text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE records(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,kind text NOT NULL,title text NOT NULL,tags text[] NOT NULL DEFAULT '{}',data jsonb NOT NULL DEFAULT '{}',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),archived_at timestamptz,UNIQUE(owner_id,id));
CREATE INDEX records_owner_kind ON records(owner_id,kind,updated_at DESC);
CREATE INDEX records_search ON records USING gin(to_tsvector('simple',title || ' ' || data::text));
CREATE INDEX records_dates ON records(owner_id,(data->>'due'));
CREATE TABLE record_versions(id bigserial PRIMARY KEY,record_id uuid NOT NULL REFERENCES records ON DELETE CASCADE,owner_id uuid NOT NULL REFERENCES users,version integer NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(record_id,version));
CREATE TABLE entity_links(owner_id uuid NOT NULL REFERENCES users,source_id uuid NOT NULL,target_id uuid NOT NULL,relation text NOT NULL,PRIMARY KEY(source_id,target_id,relation),FOREIGN KEY(owner_id,source_id) REFERENCES records(owner_id,id) ON DELETE CASCADE,FOREIGN KEY(owner_id,target_id) REFERENCES records(owner_id,id) ON DELETE CASCADE,CHECK(source_id<>target_id));
CREATE TABLE files(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users,record_id uuid, name text NOT NULL,mime text NOT NULL,size integer NOT NULL CHECK(size>0 AND size<=10485760),sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(owner_id,record_id) REFERENCES records(owner_id,id));
CREATE INDEX files_owner ON files(owner_id);
CREATE TABLE accounts(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users,name text NOT NULL,type text NOT NULL,currency text NOT NULL DEFAULT 'IDR' CHECK(currency='IDR'),archived_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,id));
CREATE TABLE debts(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users,name text NOT NULL,principal bigint NOT NULL CHECK(principal>0),apr numeric(8,4) NOT NULL CHECK(apr>=0 AND apr<=100),months integer NOT NULL CHECK(months>0 AND months<=600),start date NOT NULL,direction text NOT NULL CHECK(direction IN('borrowed','lent')),model text NOT NULL CHECK(model IN('reducing','flat')),rates jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,id));
CREATE TABLE ledger_transactions(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users,kind text NOT NULL,category text NOT NULL,date date NOT NULL,description text NOT NULL DEFAULT '',idempotency_key uuid NOT NULL,request_hash text NOT NULL,reversal_of uuid UNIQUE REFERENCES ledger_transactions,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,id),UNIQUE(owner_id,idempotency_key));
CREATE INDEX transactions_owner_date ON ledger_transactions(owner_id,date DESC);
CREATE TABLE ledger_postings(id bigserial PRIMARY KEY,owner_id uuid NOT NULL,transaction_id uuid NOT NULL,account_id uuid,amount bigint NOT NULL,FOREIGN KEY(owner_id,transaction_id) REFERENCES ledger_transactions(owner_id,id),FOREIGN KEY(owner_id,account_id) REFERENCES accounts(owner_id,id));
CREATE INDEX postings_account ON ledger_postings(owner_id,account_id);
CREATE TABLE debt_payments(id uuid PRIMARY KEY,owner_id uuid NOT NULL,debt_id uuid NOT NULL,transaction_id uuid NOT NULL UNIQUE,principal bigint NOT NULL CHECK(principal>0),interest bigint NOT NULL CHECK(interest>=0),FOREIGN KEY(owner_id,debt_id) REFERENCES debts(owner_id,id),FOREIGN KEY(owner_id,transaction_id) REFERENCES ledger_transactions(owner_id,id));
CREATE TABLE audit_logs(id bigserial PRIMARY KEY,owner_id uuid REFERENCES users,action text NOT NULL,entity_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_owner ON audit_logs(owner_id,created_at DESC);
CREATE TABLE notifications(id text PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users,title text NOT NULL,record_id uuid REFERENCES records,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE automation_runs(rule_id uuid NOT NULL REFERENCES records,scheduled_at text NOT NULL,PRIMARY KEY(rule_id,scheduled_at));
CREATE FUNCTION check_ledger_balance() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (SELECT COALESCE(sum(amount),0) FROM ledger_postings WHERE transaction_id=NEW.transaction_id) <> 0 THEN RAISE EXCEPTION 'Unbalanced ledger'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER balanced_postings AFTER INSERT OR UPDATE ON ledger_postings DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_ledger_balance();
